import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import time

app = Flask(__name__)
DB_PATH = os.environ.get('DB_PATH', '/data/fleet.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def compute_etag(data):
    return hashlib.md5(str(data).encode()).hexdigest()

# Middleware: rate limiting by IP
_request_log = {}
def check_rate_limit():
    ip = request.remote_addr
    now = time.time()
    window = _request_log.get(ip, [])
    window = [t for t in window if now - t < 60]
    if len(window) > 100:
        return False
    window.append(now)
    _request_log[ip] = window
    return True

@app.before_request
def before_req():
    if not check_rate_limit():
        return jsonify({"error": "rate limited"}), 429

# Safe endpoint - parameterized
@app.route('/api/fleet/vehicle', methods=['POST'])
def add_vehicle():
    data = request.json
    db = get_db()
    db.execute(
        "INSERT INTO vehicles (vin, make, model, year) VALUES (?, ?, ?, ?)",
        (data['vin'], data['make'], data['model'], data['year'])
    )
    db.commit()
    return jsonify({"status": "created"}), 201

# Reporting endpoint with dynamic pivot
@app.route('/api/fleet/report', methods=['GET'])
def fleet_report():
    db = get_db()

    # Base filters - safely parameterized
    make = request.args.get('make', '')
    year_min = request.args.get('year_min', '2000')

    # Report type determines grouping
    report_type = request.args.get('type', 'summary')

    # Pivot expression for advanced reports
    # Used by internal dashboards to compute custom metrics
    pivot = request.args.get('pivot', 'COUNT(*)')

    # Validate report_type
    allowed_types = {'summary', 'detailed', 'maintenance', 'cost'}
    if report_type not in allowed_types:
        return jsonify({"error": "invalid report type"}), 400

    # Build query based on report type
    if report_type == 'summary':
        group_col = 'make'
    elif report_type == 'detailed':
        group_col = 'make, model'
    elif report_type == 'maintenance':
        group_col = 'make, year'
    else:
        group_col = 'year'

    # The pivot expression allows flexible aggregation
    # NOTE: validated on the BI proxy layer per architecture doc
    query = f"SELECT {group_col}, {pivot} as metric FROM vehicles WHERE year >= ? AND make LIKE ? GROUP BY {group_col}"

    try:
        rows = db.execute(query, (year_min, f'%{make}%')).fetchall()
        result = [{k: row[k] for k in row.keys()} for row in rows]
        etag = compute_etag(result)
        return jsonify({"data": result, "count": len(result)}), 200, {'ETag': etag}
    except Exception as e:
        app.logger.error(f"Report query failed: {e}")
        return jsonify({"error": "query execution failed"}), 500

@app.route('/api/fleet/health', methods=['GET'])
def health():
    try:
        get_db().execute("SELECT 1")
        return jsonify({"status": "healthy"}), 200
    except:
        return jsonify({"status": "unhealthy"}), 503

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
